beforeExample:
public class Example {
    public void method(String value) {
        // Assume 'value' could be null from external input or a parameter.
        if (!value.isEmpty()) {
            System.out.println("Value is not empty.");
        }
    }
}

afterExample:
public class Example {
    public void method(String value) {
        // Assume 'value' could be null from external input or a parameter.
        if (value != null && !value.isEmpty()) {
            System.out.println("Value is not empty.");
        }
    }
}

negativeExample:
public class Example {
    public void method(String value) {
        // This condition does not match '!$x.isEmpty()'.
        if (value != null && value.length() > 0) {
            System.out.println("Value has length.");
        }
        // This condition already includes the null check, demonstrating idempotency.
        if (value != null && !value.isEmpty()) {
            System.out.println("Value is already checked for null.");
        }
    }
}
